 [["TextInput", "Name"], // text field
 ["RadioGroup", "Gender", ["Male", "Female"]], // radio button group
 ["CheckBox", "Do you smoke", "yes"], // checkbox
 ["TextArea", "Comments"], // text area
]);
addChild(myFieldSet);


